function mergeArrays(array1, array2) {
  const mergedArray = [...array1, ...array2];
  const uniqueObjects = mergedArray.reduce((acc, current) => {
    const existingObject = acc.find((obj) => obj.stepId === current.stepId && obj.fieldId === current.fieldId);
    if (existingObject) {
      existingObject.message = current.message;
    } else {
      acc.push(current);
    }
    return acc;
  }, []);
  return uniqueObjects;
}
